-- assessment-service: quizzes, tests, assignments and practice sets per course, their questions and the students' attempts
-- Ask 46 baseline seed, exported from the running stack by scripts/export_seed.py (Flyway reset). Edit by hand or re-export.

SELECT setval(pg_get_serial_sequence('question', 'id'), COALESCE((SELECT max(id) FROM question), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('attempt', 'id'), COALESCE((SELECT max(id) FROM attempt), 0) + 1, false);
